			this.spellArmed = false;
			this.spellAim = null;
			this.missileTargets = [];
			this.tip = null;
			this.pushLog(`${unit.name} usa ${PROVOKE.name}: ${foes.map((f) => f.name).join(", ")} ${foes.length > 1 ? "voltam-se" : "volta-se"} contra ${unit.name}.`);
