								const a = m.seed + spark * 2.399 + this.time * (2.2 + spark * .09);
								const radius = tile * (.12 + spark * 7 % 6 * .018);
								const x = head.x + Math.cos(a) * radius;
								const y = head.y + Math.sin(a) * radius * .55;
