			shaft.addColorStop(.55, `hsla(${h}, ${s}%, 82%, ${(medium ? .55 : hands ? .435 : .32) * fade})`);
			shaft.addColorStop(.88, `hsla(${h}, ${s}%, 78%, ${(medium ? .28 : hands ? .22 : .16) * fade})`);
