			core.addColorStop(.7, `hsla(${h}, 80%, 96%, ${(medium ? .85 : hands ? .675 : .5) * fade})`);
			core.addColorStop(1, `hsla(${h}, 80%, 90%, 0)`);
			ctx.fillStyle = core;
