			bloom.addColorStop(.35, `hsla(${h}, ${s}%, 72%, ${(medium ? .38 : hands ? .29 : .2) * fade})`);
			bloom.addColorStop(1, `hsla(${h}, ${s}%, 60%, 0)`);
