		const cx = thick ? width * .23 : 0, radius = width * (thick ? .17 : .23);
		const top = height * .87, bevel = thick ? height * .08 : 0;
		const frame = new Shape();
		frame.moveTo(-width / 2, 0);
		frame.lineTo(-width / 2, height);
		frame.lineTo(width / 2, height);
		frame.lineTo(width / 2, 0);
		frame.lineTo(cx + radius, 0);
		frame.lineTo(cx + radius, top - bevel);
		frame.lineTo(cx + radius * .8, top);
		frame.lineTo(cx - radius * .8, top);
		frame.lineTo(cx - radius, top - bevel);
		frame.lineTo(cx - radius, 0);
		frame.closePath();
