			const hole = new Path();
			hole.moveTo(-width * .36, height * .26);
			hole.lineTo(-width * .36, height * .68);
			hole.lineTo(-width * .1, height * .68);
			hole.lineTo(-width * .1, height * .26);
			hole.closePath();
