			for (let i = 0; i < 4; i++) box(width * .017, tile * .055, height * .42, -width * .33 + i * width * .067, 0, height * .47, metal);
			for (const z of [.38, .55]) box(width * .26, tile * .065, height * .018, -width * .23, 0, height * z, metal);
