			leaf.lineTo(cx + radius, 0);
			leaf.lineTo(cx + radius, top - bevel);
			leaf.lineTo(cx + radius * .8, top);
			leaf.lineTo(cx - radius * .8, top);
			leaf.lineTo(cx - radius, top - bevel);
