	//#region src/game/gfx/three/ElementFlipbookAtlas.ts
	const atlases = /* @__PURE__ */ new Map();
	/** Load each element/layer 4x4 atlas once; the element emitter chooses the renderer per version. */
	function loadElementFlipbook(element, layer = "main", version = 1) {
		const key = `${version}:${element}:${layer}`;
		const filename = version === 2 ? `${element}-v2-${layer}-flipbook-4x4.png` : layer === "main" ? `${element}-flipbook-4x4.png` : `${element}-${layer}-flipbook-4x4.png`;
		const cached = atlases.get(key);
		if (cached) return cached;
		const loading = new TextureLoader().loadAsync(`/game/fx/${filename}`).then((texture) => {
			texture.colorSpace = SRGBColorSpace;
			texture.generateMipmaps = true;
			texture.minFilter = LinearMipmapLinearFilter;
			texture.magFilter = LinearFilter;
			texture.wrapS = ClampToEdgeWrapping;
			texture.wrapT = ClampToEdgeWrapping;
			return texture;
		}).catch((error) => {
			atlases.delete(key);
			throw error;
		});
		atlases.set(key, loading);
		return loading;
	}
