				i / n;
				const arrival = target ? .5 + MathUtils.clamp(new Vector2(target.position.x - this.origin.x, target.position.y - this.origin.y).dot(this.direction) / (this.settings.radius * this.tile), 0, 1) * .26 : .5;
				const age = Math.max(0, t - arrival);
				const distance = age * this.settings.debrisVelocity * this.tile * 1.4;
