				this.dummy.position.x = radial + this.direction.x * distance + Math.sin(i * 8.31 + age * 9) * this.settings.turbulence * this.tile * .25;
				this.dummy.position.y = side + Math.cos(i * 5.17 + age * 7) * this.settings.turbulence * this.tile * .2;
				this.dummy.position.z = this.tile * (.14 + Math.abs(Math.sin(age * 9 + i)) * this.settings.height * .3);
				const fade = target ? 1 - MathUtils.smoothstep(age, .2, .75) : 1 - MathUtils.smoothstep(t, .72, 1.1);
				this.dummy.scale.setScalar(Math.max(.001, fade * (.4 + i % 4 * .15)));
				this.dummy.rotation.set(age * 7 + i, age * 9, age * 4);
